+      studentDisplayEligibleFinal: source.student_display_eligible_final === true,
+      completeStudentFacingQuestion: source.complete_student_facing_question === true,
+      attemptableInBeta: source.attemptable_in_beta === true,
+    },
+    display: {
+      displayPosture: normalizeString(source.display_posture),
