+  const summary = cloneJsonValue(readObject(source.summary));
+  const rows = asArray(source.rows).map(normalizePostureRow);
+  const rowByQuestionKey = new Map();
+
+  rows.forEach((row) => {
+    const questionKey = normalizeString(row.question_key);
+    if (questionKey) rowByQuestionKey.set(questionKey, row);
+  });
+
+  const staleAvailabilityGateStatus = buildStaleAvailabilityGateStatus(summary);
+
+  return {
+    source: V1_FULL_BETA_POSTURE_SOURCE,
+    schemaVersion: normalizeString(source.schema_version),
+    summary,
+    rows,
+    rowByQuestionKey,
+    staleAvailabilityGateStatus,
+    rejectedAvailabilityBoundaries: buildRejectedAvailabilityBoundaries(staleAvailabilityGateStatus),
+    expectedRowCount: FULL_BETA_POSTURE_EXPECTED_ROW_COUNT,
+  };
+}
+
+export function getFullBetaPostureRowByQuestionKey(readModel = {}, questionKey = '') {
+  const normalizedQuestionKey = normalizeString(questionKey);
+
+  if (readModel.rowByQuestionKey instanceof Map) {
+    return readModel.rowByQuestionKey.get(normalizedQuestionKey) ?? null;
+  }
+
+  return asArray(readModel.rows).find((row) => row.question_key === normalizedQuestionKey) ?? null;

